SELECT CASE WHEN cost >= 81 THEN 'high' WHEN cost >= 35 THEN 'mid' ELSE 'low' END AS cost_bucket, SUM(cost) AS total_cost, COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) AS delivered_count, MAX(shipped_date) AS latest_shipped_date FROM shipments WHERE order_id IS NOT NULL AND (order_id = 23 OR cost >= 67) GROUP BY CASE WHEN cost >= 81 THEN 'high' WHEN cost >= 35 THEN 'mid' ELSE 'low' END HAVING COUNT(CASE WHEN status = 'DELIVERED' THEN 1 END) >= 3;
